#!/usr/bin/env bash
# Question 15: Back up etcd. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -f "${Q15_BACKUP}"
mkdir -p "$(dirname "${Q15_BACKUP}")"
kubectl -n default create configmap "${Q15_MARKER}" --from-literal=created="$(date -Is)" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
rm -f "${Q15_STATUS_FILE}"
